import React, { useState } from 'react';

const RegistroDocenteForm = () => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({}); // para guardar valores

  const steps = [
    'Datos del Docente',
    'Datos del Nacimiento',
    'Dirección Actual',
    'Títulos',
  ];

  const handleNext = () => setStep((prev) => Math.min(prev + 1, steps.length));
  const handlePrev = () => setStep((prev) => Math.max(prev - 1, 1));

  // Manejo genérico para inputs controlados
  const handleChange = (e) => {
    const { name, value, files, type } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === 'file' ? files : value,
    }));
  };

  const Tabs = () => (
    <div className="flex justify-between mb-6">
      {steps.map((label, index) => (
        <div
          key={index}
          className={`flex-1 text-center p-2 border-b-4 transition-all duration-300 ${
            step === index + 1
              ? 'border-blue-500 font-bold text-blue-600'
              : 'border-gray-300 text-gray-500'
          }`}
        >
          {label}
        </div>
      ))}
    </div>
  );

  const Buttons = ({ isFinalStep }) => (
    <div className="flex justify-between mt-6">
      <button
        onClick={handlePrev}
        disabled={step === 1}
        className="bg-gray-300 text-gray-800 px-4 py-2 rounded disabled:opacity-50"
      >
        Anterior
      </button>
      <button
        onClick={isFinalStep ? handleSubmit : handleNext}
        className="bg-blue-500 text-white px-4 py-2 rounded"
      >
        {isFinalStep ? 'Finalizar' : 'Siguiente'}
      </button>
    </div>
  );

  const handleSubmit = () => {
    console.log('Datos del formulario:', formData);
    alert('Formulario enviado correctamente');
    // Aquí puedes enviar `formData` al backend
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="w-[900px] h-[750px] bg-white shadow-xl p-10 rounded-2xl overflow-y-auto">
        <Tabs />

        {/* Paso 1 */}
        {step === 1 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {[
              ['apellidoPaterno', 'Apellido Paterno'],
              ['apellidoMaterno', 'Apellido Materno'],
              ['nombres', 'Nombres'],
              ['ci', 'CI'],
              ['expedido', 'Expedido'],
              ['complemento', 'Complemento'],
              ['correo', 'Correo Electrónico', 'email'],
              ['celular', 'Celular'],
            ].map(([name, placeholder, type = 'text']) => (
              <input
                key={name}
                name={name}
                type={type}
                placeholder={placeholder}
                className="border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
                value={formData[name] || ''}
                onChange={handleChange}
              />
            ))}
          </div>
        )}

        {/* Paso 2 */}
        {step === 2 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {[
              ['pais', 'País'],
              ['lugarNacimiento', 'Lugar de Nacimiento'],
              ['nroOficialia', 'Nro de Oficialía'],
              ['nroLibro', 'Nro de Libro'],
              ['nroPartida', 'Nro de Partida'],
              ['nroFolio', 'Nro de Folio'],
            ].map(([name, placeholder]) => (
              <input
                key={name}
                name={name}
                placeholder={placeholder}
                className="border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
                value={formData[name] || ''}
                onChange={handleChange}
              />
            ))}
            <div>
              <label className="block mb-2 text-sm text-gray-600">
                Adjuntar Documentación
              </label>
              <input
                name="documentacionNacimiento"
                type="file"
                className="border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
                onChange={handleChange}
              />
            </div>
          </div>
        )}

        {/* Paso 3 */}
        {step === 3 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {[
              ['ciudad', 'Ciudad / Municipio'],
              ['localidad', 'Localidad / Comunidad'],
              ['zona', 'Zona / Urbanización / Villa'],
              ['avenida', 'Avenida / Calle'],
              ['numeroVivienda', 'Número de Vivienda'],
            ].map(([name, placeholder]) => (
              <input
                key={name}
                name={name}
                placeholder={placeholder}
                className="border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
                value={formData[name] || ''}
                onChange={handleChange}
              />
            ))}
            <div>
              <label className="block mb-2 text-sm text-gray-600">
                Adjuntar Documentación
              </label>
              <input
                name="documentacionDireccion"
                type="file"
                className="border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
                onChange={handleChange}
              />
            </div>
          </div>
        )}

        {/* Paso 4 */}
        {step === 4 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {[
              ['formacion', 'Formación Académica'],
              ['institucion', 'Institución'],
              ['anioGraduacion', 'Año de Graduación'],
              ['especialidad', 'Especialidad'],
            ].map(([name, placeholder]) => (
              <input
                key={name}
                name={name}
                placeholder={placeholder}
                className="border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
                value={formData[name] || ''}
                onChange={handleChange}
              />
            ))}
            <div>
              <label className="block mb-2 text-sm text-gray-600">
                Adjuntar Título Académico
              </label>
              <input
                name="tituloAcademico"
                type="file"
                className="border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
                onChange={handleChange}
              />
            </div>
          </div>
        )}

        <Buttons isFinalStep={step === steps.length} />
      </div>
    </div>
  );
};

export default RegistroDocenteForm;
